-- Bookkeeping academic bank correction
-- Owner request: audit and fix the Bookkeeping course against FOA-ACA-STD-001 v1.1.
-- Preserves assessment IDs, attempts, submissions, answers, marks, pass rules, and learner progress.

begin;

create temporary table _bookkeeping_question_fix (
  module_number integer not null,
  assessment_kind text not null,
  question_number integer not null,
  question_text text not null,
  option_a text not null,
  option_b text not null,
  option_c text not null,
  option_d text not null,
  correct_answer text not null,
  primary key (module_number, assessment_kind, question_number)
) on commit drop;


do $$
declare
  expected_count integer := 840;
  matched_count integer;
begin
  if exists (
    select 1
    from public.assessment_answers answer
    join public.assessment_attempts attempt on attempt.id = answer.attempt_id
    join public.assessments assessment on assessment.id = attempt.assessment_id
    where assessment.course_id = 'fcbe0c39-c31f-4a39-833f-7b89d553bef2'::uuid
  ) then
    raise exception 'Bookkeeping bank guard failed: recorded learner answers exist; preserve them before changing option positions';
  end if;

  select count(*) into matched_count
  from _bookkeeping_question_fix f
  join public.course_modules m
    on m.course_id = 'fcbe0c39-c31f-4a39-833f-7b89d553bef2'::uuid
   and m.module_number = f.module_number
  join public.assessments a
    on a.course_id = m.course_id
   and a.module_id = m.id
   and a.active is true
   and a.status = 'published'
   and lower(a.title) like '%' || f.assessment_kind || '%'
  join public.assessment_questions q
    on q.assessment_id = a.id
   and q.question_number = f.question_number;

  if matched_count <> expected_count then
    raise exception 'Bookkeeping bank guard failed: matched %, expected %', matched_count, expected_count;
  end if;
end $$;

update public.assessment_questions q
set question_text = f.question_text,
    option_a = f.option_a,
    option_b = f.option_b,
    option_c = f.option_c,
    option_d = f.option_d,
    correct_answer = f.correct_answer
from _bookkeeping_question_fix f
join public.course_modules m
  on m.course_id = 'fcbe0c39-c31f-4a39-833f-7b89d553bef2'::uuid
 and m.module_number = f.module_number
join public.assessments a
  on a.course_id = m.course_id
 and a.module_id = m.id
 and a.active is true
 and a.status = 'published'
 and lower(a.title) like '%' || f.assessment_kind || '%'
where q.assessment_id = a.id
  and q.question_number = f.question_number;

update public.assessments
set description = replace(description, 'Professional Certificate in Bookkeeping', 'Bookkeeping & Financial Administration — Professional Short Course'),
    updated_at = now()
where course_id = 'fcbe0c39-c31f-4a39-833f-7b89d553bef2'::uuid
  and active is true
  and status = 'published';

commit;
